/* ====== IKEA BESTÅ replica — stylesheet ====== */
:root{
  --blue:#0058a3; --blue-d:#004f93; --yellow:#ffdb00; --ink:#111;
  --g1:#484848; --g2:#767676; --g3:#a5a5a5;
  --line:#dfdfdf; --line2:#ebebeb;
  --bg:#fff; --bg2:#f5f5f5; --bg3:#fafafa;
  --red:#e00751; --green:#0a8a00;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{font-family:Arial,"Helvetica Neue",Helvetica,"Segoe UI",sans-serif;color:var(--ink);background:#fff;font-size:14px;line-height:1.45;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none;cursor:pointer}
button{font-family:inherit;font-size:inherit;cursor:pointer;border:0;background:none;color:inherit;padding:0}
img{display:block;max-width:100%}
ul{margin:0;padding:0;list-style:none}
h1,h2,h3,h4{margin:0;font-weight:700}
p{margin:0}
sup{font-size:.55em;top:-.6em;position:relative;font-weight:700}
.wrap{max-width:1440px;margin:0 auto;padding:0 40px}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}

/* ---------- top bar ---------- */
.topbar{background:#111;color:#fff;font-size:13px}
.topbar .in{max-width:1440px;margin:0 auto;padding:0 24px;height:42px;display:flex;align-items:center;gap:18px}
.topbar .l{display:flex;align-items:center;gap:8px}
.topbar .c{flex:1;display:flex;justify-content:center}
.topbar .c a{display:flex;align-items:center;gap:8px}
.topbar .r{display:flex;align-items:center;gap:26px}
.topbar .r button{display:flex;align-items:center;gap:8px;color:#fff}
.topbar svg{stroke:#fff}

/* ---------- header ---------- */
.hdr{background:#fff;border-bottom:1px solid transparent}
.hdr .in{max-width:1440px;margin:0 auto;padding:12px 24px;display:flex;align-items:center;gap:8px;height:78px}
.logo{width:88px;flex:0 0 88px}
.logo img{width:88px;height:auto}
.hnav{display:flex;gap:4px;margin-left:22px}
.hnav button{padding:9px 12px;border-radius:4px;font-size:14px}
.hnav button:hover{background:#f0f0f0;text-decoration:underline}
.hnav button.on{font-weight:700;border-bottom:2px solid var(--ink);border-radius:0}
.search{flex:1;max-width:760px;margin:0 auto;position:relative;display:flex;align-items:center}
.search .box{flex:1;display:flex;align-items:center;background:#f5f5f5;border-radius:100px;height:48px;padding:0 8px 0 16px;border:1px solid transparent;transition:.15s}
.search.filled .box,.search.focus .box{background:#fff;border-color:#929292;box-shadow:0 2px 8px rgba(0,0,0,.08)}
.search input{flex:1;border:0;outline:0;background:transparent;font-size:16px;height:100%;color:#111}
.search .ibtn{width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#484848}
.search .ibtn:hover{background:#e8e8e8}
.search .cx{display:none}
.search.filled .cx,.search.focus .cx{display:flex}
.sug{position:absolute;top:56px;left:0;right:0;background:#fff;border-radius:8px;box-shadow:0 8px 30px rgba(0,0,0,.22);padding:8px 0;z-index:60;display:none}
.sug.on{display:block}
.sug a{display:flex;align-items:center;gap:12px;padding:10px 18px;font-size:15px}
.sug a:hover{background:#f0f0f0}
.hright{display:flex;align-items:center;gap:6px;margin-left:8px}
.hright .acc{display:flex;align-items:center;gap:8px;padding:9px 12px;border-radius:4px;font-size:14px}
.hright .acc:hover{background:#f0f0f0;text-decoration:underline}
.iconbtn{width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;position:relative}
.iconbtn:hover{background:#f0f0f0}
.badge{position:absolute;top:2px;right:2px;min-width:20px;height:20px;border-radius:10px;background:var(--blue);color:#fff;font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;padding:0 5px}

/* ---------- pills ---------- */
.pills{display:flex;gap:14px;padding:14px 0 26px;overflow:hidden}
.pill{display:flex;align-items:center;gap:10px;border:1px solid var(--line);border-radius:100px;padding:8px 18px 8px 10px;white-space:nowrap;font-size:14px;background:#fff}
.pill:hover{border-color:#929292}
.pill.on{border-color:var(--blue);border-bottom-width:3px}
.pill .ic{width:36px;height:36px;border-radius:50%;background:#f5f5f5;display:flex;align-items:center;justify-content:center;overflow:hidden;flex:0 0 auto}
.pill .ic img{width:100%;height:100%;object-fit:cover}

/* ---------- meganav ---------- */
.meganav{border-bottom:1px solid var(--line);background:#fff;padding:22px 0 34px}
.meganav .tabs{display:flex;gap:0;margin-bottom:26px;overflow:hidden}
.meganav .tabs button{border:1px solid var(--line);padding:11px 20px;font-size:14px;background:#fff;margin-right:-1px;white-space:nowrap}
.meganav .tabs button:first-child{border-radius:4px 0 0 4px}
.meganav .tabs button:last-child{border-radius:0 4px 4px 0}
.meganav .tabs button.on{border:2px solid var(--blue);font-weight:700;position:relative;z-index:2}
.meganav .body{display:grid;grid-template-columns:300px 1fr 260px 340px;gap:24px}
.meganav .left a{display:block;font-size:19px;font-weight:700;padding:7px 0}
.meganav .left a:first-child{font-size:19px}
.meganav .left a:hover{text-decoration:underline}
.meganav .col a{display:block;padding:6px 0;font-size:14px}
.meganav .col a:hover{text-decoration:underline}
.meganav .col h4{font-size:15px;margin-bottom:4px}
.meganav .col h4:empty{display:none}
.meganav .promo{background:var(--bg2)}
.meganav .promo img{width:100%;height:190px;object-fit:cover}
.meganav .promo .t{padding:20px;font-size:17px;font-weight:700;color:#fff}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;border-radius:100px;font-weight:700;font-size:14px;padding:14px 24px;text-align:center}
.btn.blue{background:var(--blue);color:#fff}
.btn.blue:hover{background:var(--blue-d)}
.btn.black{background:#111;color:#fff}
.btn.black:hover{background:#333}
.btn.ghost{border:1px solid var(--ink);background:#fff;color:var(--ink)}
.btn.ghost:hover{background:#f0f0f0}
.btn.gray{background:#e8e8e8;color:#929292;cursor:not-allowed}
.btn.full{width:100%}

/* ---------- home hero ---------- */
.hero{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding-bottom:60px}
.hero .big{position:relative;background:#f5f5f5}
.hero .big img{width:100%;height:530px;object-fit:cover}
.hero .tag{position:absolute;top:14px;left:14px;background:var(--blue);color:#fff;font-size:12px;font-weight:700;padding:5px 10px}
.hero .pause{position:absolute;top:14px;right:64px;width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.85);display:flex;align-items:center;justify-content:center}
.hero .col{display:flex;flex-direction:column;gap:12px}
.hero .card{position:relative;overflow:hidden;background:#f5f5f5}
.hero .card img{width:100%;object-fit:cover}
.hero .card.top img{height:370px}
.hero .card .new{position:absolute;top:14px;left:14px;background:#e0651a;color:#fff;font-size:12px;font-weight:700;padding:5px 10px}
.hero .card .cap{position:absolute;left:0;right:0;bottom:0;padding:16px 18px;color:#fff;font-size:23px;font-weight:700;background:linear-gradient(transparent,rgba(0,0,0,.62));display:flex;justify-content:space-between;align-items:flex-end}
.hero .card .cap span{text-decoration:underline;text-underline-offset:4px}
.hero .row{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.hero .row .card img{height:148px}
.hero .row .card .cap{font-size:15px}

/* ---------- cookie ---------- */
.cookie{position:fixed;left:0;right:0;bottom:0;background:#fff;border-top:1px solid var(--line);box-shadow:0 -4px 20px rgba(0,0,0,.08);z-index:70;padding:14px 24px}
.cookie .in{max-width:1440px;margin:0 auto;display:flex;align-items:center;gap:24px;font-size:13px}
.cookie p{flex:1;color:#333}
.cookie .acts{display:flex;gap:12px;flex:0 0 auto}

/* ---------- search page ---------- */
.info-banner{border-left:3px solid var(--blue);background:#f7f7f7;padding:14px 18px;margin:18px 0 26px;font-size:14px}
.search-head{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start;margin-bottom:16px}
.search-head h1{font-size:26px;margin-top:6px}
.design-box{border:1px solid var(--line);padding:16px 18px;display:flex;gap:14px}
.design-box .t{font-weight:700}
.design-box a{color:var(--blue);text-decoration:underline;font-size:13px}
.search-body{display:grid;grid-template-columns:250px 1fr;gap:34px;padding-bottom:80px}
.filters{border-right:1px solid var(--line2)}
.acc{border-bottom:1px solid var(--line2)}
.acc>button{width:100%;display:flex;justify-content:space-between;align-items:center;padding:16px 4px;font-size:14px}
.acc>button b{font-weight:700;text-decoration:underline;text-underline-offset:3px}
.acc .panel{display:none;padding:0 4px 18px}
.acc.open .panel{display:block}
.acc.open>button svg{transform:rotate(180deg)}
.acc .cnt{display:flex;justify-content:space-between;align-items:center;padding:12px 4px;border-bottom:1px solid var(--line2);font-size:14px}
.radio{display:flex;align-items:center;gap:12px;padding:10px 0;font-size:14px;cursor:pointer}
.radio .dot{width:20px;height:20px;border-radius:50%;border:2px solid #767676;flex:0 0 auto;display:flex;align-items:center;justify-content:center}
.radio.on .dot{border-color:var(--ink)}
.radio.on .dot:after{content:'';width:10px;height:10px;border-radius:50%;background:var(--ink)}
.swatches{display:grid;grid-template-columns:1fr 1fr;gap:6px 10px}
.sw{display:flex;flex-direction:column;align-items:center;gap:6px;padding:8px 0;border-radius:4px}
.sw:hover{background:#f5f5f5}
.sw .c{width:56px;height:56px;border-radius:50%;border:1px solid rgba(0,0,0,.15);display:flex;align-items:center;justify-content:center}
.sw.on .c{box-shadow:0 0 0 2px #fff,0 0 0 4px var(--ink)}
.sw span{font-size:12px;color:#484848}
.chips{display:flex;gap:8px;margin-bottom:16px;min-height:36px;align-items:center;flex-wrap:wrap}
.chip{display:inline-flex;align-items:center;gap:10px;background:#f0f0f0;border-radius:100px;padding:8px 14px;font-size:13px;font-weight:700}
.chip button{display:flex}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px 16px}
.card{position:relative;display:flex;flex-direction:column}
.card .cmpl{display:flex;align-items:center;gap:8px;font-size:13px;margin-bottom:10px;cursor:pointer}
.card .cmpl input{width:18px;height:18px;accent-color:#111}
.card .thumbwrap{position:relative;background:#f5f5f5}
.card .thumbwrap img{width:100%;aspect-ratio:1/1;object-fit:contain}
.card .fav{position:absolute;right:10px;bottom:10px;width:40px;height:40px;border-radius:50%;background:#fff;display:flex;align-items:center;justify-content:center;box-shadow:0 1px 4px rgba(0,0,0,.15)}
.card .tag{position:absolute;left:0;bottom:16px;background:var(--red);color:#fff;font-size:12px;font-weight:700;padding:4px 8px}
.card .info{padding:12px 0 0;position:relative}
.card .fam{color:var(--blue);font-weight:700;font-size:13px;margin-bottom:2px}
.card .nm{font-weight:700;font-size:14px}
.card .ds{font-size:13px;color:#111;margin-top:2px}
.card .pr{margin-top:8px;font-size:24px;font-weight:700}
.card .sv{color:var(--blue);font-weight:700;font-size:13px;margin-top:4px}
.card .rg{font-size:12px;color:#484848;margin-top:2px}
.card .dt{font-size:12px;color:#484848}
.card .rt{display:flex;align-items:center;gap:6px;font-size:12px;color:#484848;margin-top:8px}
.card .mo{font-size:13px;text-decoration:underline;margin-top:8px;display:inline-block}
.card .addb{position:absolute;right:0;top:72px;width:40px;height:40px;border-radius:50%;background:var(--blue);color:#fff;display:flex;align-items:center;justify-content:center}
.card .addb:hover{background:var(--blue-d)}
.stars{color:#111;letter-spacing:1px;font-size:13px}
.stars .off{color:#ccc}
.rc{color:#484848;text-decoration:underline;font-size:12px}

/* compare bar */
.cmpbar{position:sticky;bottom:0;background:#fff;border-top:1px solid var(--line);box-shadow:0 -4px 18px rgba(0,0,0,.08);padding:14px 0;z-index:40;display:flex;align-items:center;gap:20px}
.cmpbar .close{text-decoration:underline;font-weight:700;margin-right:auto}
.cmpbar .cnt2{font-size:14px;color:#484848}
.cmpbar .thumbs{display:flex;gap:8px}
.cmpbar .thumbs img{width:52px;height:52px;object-fit:contain;background:#f5f5f5}
.cmpbar .thumbs span{width:52px;height:52px;background:#f5f5f5;display:block}

/* ---------- compare page ---------- */
.cmp-title{font-size:36px;margin:26px 0 40px}
.cmp-table{display:grid;gap:0;padding-bottom:80px}
.cmp-head{display:grid;grid-template-columns:200px repeat(var(--cols),1fr);gap:0}
.cmp-col{position:relative;padding:0 22px}
.cmp-col .x{position:absolute;top:0;left:22px;width:32px;height:32px;display:flex;align-items:center;justify-content:center;color:#767676}
.cmp-col .x:hover{color:#111}
.cmp-col .im{background:#f5f5f5;margin-top:34px}
.cmp-col .im img{width:100%;aspect-ratio:1/1;object-fit:contain}
.cmp-col .fav{position:absolute;right:32px;bottom:10px;width:40px;height:40px;border-radius:50%;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.15);display:flex;align-items:center;justify-content:center}
.cmp-col .fam{color:var(--blue);font-weight:700;font-size:13px;margin-top:14px}
.cmp-col .nm{font-weight:700}
.cmp-col .ds{font-size:13px}
.cmp-col .pr{font-size:26px;font-weight:700;margin-top:6px}
.cmp-col .sv{color:var(--blue);font-weight:700;font-size:13px}
.cmp-col .rg,.cmp-col .dt{font-size:12px;color:#484848}
.cmp-row-h{background:#f5f5f5;font-weight:700;padding:14px 16px}
.cmp-row-c{padding:14px 22px;font-size:14px;border-bottom:1px solid var(--line2)}
.cmp-section{margin-top:34px}

/* ---------- product detail ---------- */
.crumbs{display:flex;flex-wrap:wrap;gap:8px;font-size:13px;color:#484848;padding:18px 0 22px}
.crumbs a:hover{text-decoration:underline}
.crumbs .sep{color:#767676}
.pd{display:grid;grid-template-columns:120px 1fr 460px;gap:22px;align-items:start}
.pd .thumbs{display:flex;flex-direction:column;gap:8px}
.pd .thumbs button{border:1px solid transparent;background:#f5f5f5;width:88px;height:88px;display:flex;align-items:center;justify-content:center}
.pd .thumbs button.on{border-color:#111}
.pd .thumbs img{max-width:76px;max-height:76px;object-fit:contain}
.pd .main{position:relative;background:#f5f5f5}
.pd .main img{width:100%;aspect-ratio:1/1;object-fit:contain}
.pd .ovbtns{position:absolute;right:18px;bottom:18px;display:flex;gap:12px}
.pd .ovbtns button{display:flex;align-items:center;gap:8px;background:#111;color:#fff;border-radius:100px;padding:11px 18px;font-size:13px;font-weight:700}
.pd-info{padding-right:8px}
.pd-info .fam{color:var(--blue);font-weight:700;font-size:14px}
.pd-info h1{font-size:16px;margin-top:4px}
.pd-info .desc{font-size:16px;margin-top:2px}
.pd-info .pr{font-size:34px;font-weight:700;margin-top:14px}
.pd-info .sv{color:var(--blue);font-weight:700;font-size:15px;margin-top:6px}
.pd-info .rg{font-size:13px;color:#484848;margin-top:4px}
.pd-info .rt{display:flex;align-items:center;gap:8px;margin-top:12px}
.pd-info .note{display:flex;gap:8px;align-items:flex-start;font-size:13px;color:#484848;margin-top:12px}
.pd-sec{margin-top:26px;border-top:1px solid var(--line2);padding-top:22px}
.pd-sec h3{font-size:15px;margin-bottom:4px}
.pd-sec .sub{font-size:13px;color:#484848;margin-bottom:12px}
.swrow{display:flex;flex-wrap:wrap;gap:10px}
.swrow button{width:74px;height:58px;background:#f5f5f5;display:flex;align-items:center;justify-content:center;border:2px solid transparent}
.swrow button.on{border-color:#111}
.swrow button.more{font-weight:700;font-size:13px;background:#fff;border:1px solid var(--line)}
.swrow img{max-width:62px;max-height:46px;object-fit:contain}
.htg{display:flex;flex-direction:column;gap:14px}
.htg .r{display:flex;gap:10px;align-items:flex-start;font-size:14px}
.htg .r b{display:block}
.htg .r .s{font-size:13px;color:#484848}
.htg .dot{width:10px;height:10px;border-radius:50%;background:#ccc;flex:0 0 auto;margin-top:6px}
.htg .dot.g{background:var(--green)}
.qtyrow{display:flex;gap:12px;align-items:center;margin-top:18px}
.stepper{display:flex;align-items:center;border:1px solid var(--line);border-radius:100px;height:52px;padding:0 6px;gap:4px}
.stepper button{width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:20px}
.stepper button:hover{background:#f0f0f0}
.stepper button:disabled{color:#ccc;cursor:not-allowed}
.stepper .v{min-width:34px;text-align:center;font-size:16px;font-weight:700}
.svcbox{background:#f5f5f5;padding:16px 18px;margin-top:20px;display:flex;gap:12px;align-items:flex-start;font-size:14px}
.points{display:flex;gap:12px;align-items:flex-start;margin-top:18px;font-size:14px}
.points .p1{width:24px;height:24px;border-radius:50%;background:var(--yellow);display:flex;align-items:center;justify-content:center;flex:0 0 auto}
.infobox{border:1px solid var(--line);padding:16px 18px;margin-top:18px;font-size:14px;display:flex;gap:12px}
.infobox .t{font-weight:700;margin-bottom:2px}

/* tabs */
.pdtabs{margin-top:44px;background:#f5f5f5;padding:0 0 0}
.pdtabs .bar{display:flex;gap:0;border-bottom:1px solid var(--line);background:#f5f5f5}
.pdtabs .bar button{padding:20px 26px;font-size:15px;color:#484848}
.pdtabs .bar button.on{color:#111;font-weight:700;box-shadow:inset 0 -3px 0 var(--ink)}
.pdtabs .panel{background:#fff;padding:34px 34px 46px}
.meas{display:grid;grid-template-columns:1fr 1fr;gap:34px;align-items:start}
.meas .ill{background:#f5f5f5}
.meas .ill img{width:100%;object-fit:contain}
.mtable{border:1px solid var(--line);border-radius:6px;overflow:hidden}
.mtable .h{padding:18px 22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;cursor:pointer;font-weight:700}
.mtable .grid2{display:grid;grid-template-columns:1fr 1fr;background:#f5f5f5;gap:1px;padding:1px 0}
.mtable .cell{padding:18px 22px;background:#fff}
.mtable .cell .k{font-weight:700;font-size:13px;color:#484848}
.mtable .cell .v{font-size:16px;text-align:right}
.mtable .cell{display:flex;justify-content:space-between;align-items:baseline}
.mtable .row{padding:16px 22px;border-top:1px solid var(--line);display:flex;justify-content:space-between}
.inc{display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px;align-items:start}
.inc .list{grid-column:span 2;display:grid;grid-template-columns:1fr 1fr;gap:16px}
.compc{border:1px solid var(--line);padding:16px;display:flex;gap:14px}
.compc .im{width:86px;height:70px;background:#f5f5f5;display:flex;align-items:center;justify-content:center;flex:0 0 auto}
.compc .im img{max-width:76px;max-height:60px;object-fit:contain}
.compc .q{font-weight:700;font-size:14px}
.compc .nm{font-size:13px}
.compc .ds{font-size:12px;color:#484848}
.compc .art{display:inline-block;background:#111;color:#fff;font-size:11px;font-weight:700;padding:3px 7px;margin-top:8px;letter-spacing:.5px}
.inc .hero2{background:#f5f5f5}
.inc .hero2 img{width:100%;object-fit:contain}

/* reviews summary block */
.revsec{background:#f5f5f5;padding:40px 0}
.revcard{background:#fff;display:grid;grid-template-columns:300px 1fr;gap:0}
.revcard .l{background:#f5f5f5;padding:34px 30px;font-size:24px;font-weight:700}
.revcard .r{padding:34px 40px;display:flex;gap:60px;align-items:flex-start}
.revcard .bignum{font-size:40px;font-weight:700}
.revcard .rev{font-size:34px;font-weight:700}

/* accessories */
.access{margin-top:50px;padding-bottom:60px}
.access .hd{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}
.access .hd h2{font-size:22px}
.accgrid{display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}
.accgrid .it{background:#fff;padding:0}
.accgrid img{width:100%;aspect-ratio:1/1;object-fit:cover}

/* ---------- bag ---------- */
.bagwrap{display:grid;grid-template-columns:1fr 500px;gap:44px;padding:30px 0 70px;align-items:start}
.bagwrap h1{font-size:38px;margin-bottom:24px}
.dcards{display:grid;grid-template-columns:1fr 1fr 1fr;border:1px solid var(--line)}
.dcard{padding:18px;border-right:1px solid var(--line);font-size:13px}
.dcard:last-child{border-right:0}
.dcard .hd{display:flex;gap:10px;font-weight:700;font-size:15px;margin-bottom:10px}
.dcard .l{color:var(--blue);text-decoration:underline;font-weight:700}
.dcard .g{color:var(--g1)}
.pickup{background:#f5f5f5;padding:16px 18px;font-size:14px;display:flex;gap:12px;margin-bottom:34px}
.pickup a{text-decoration:underline}
.line{display:grid;grid-template-columns:150px 1fr auto;gap:20px;padding:26px 0;border-bottom:1px solid var(--line2)}
.line .im{background:#f5f5f5;display:flex;align-items:center;justify-content:center}
.line .im img{width:100%;aspect-ratio:1/1;object-fit:contain}
.line .art{font-size:12px;background:#f5f5f5;padding:5px 8px;display:inline-block;margin-top:8px}
.line h3{font-size:16px}
.line .ds{font-size:14px;margin-top:2px}
.line .sv{color:var(--blue);font-weight:700;font-size:13px;margin-top:6px;display:block}
.line .unit{font-size:13px;color:#484848}
.line .lnk{text-decoration:underline;font-size:14px;display:inline-block;margin-top:12px}
.line .avail{margin-top:12px;font-size:13px}
.line .avail div{display:flex;gap:8px;align-items:center;padding:2px 0}
.line .acts{display:flex;align-items:center;gap:18px;margin-top:14px}
.line .acts .sp{flex:1}
.line .tot{font-size:16px;font-weight:700;text-align:right}
.asmb{background:#f5f5f5;padding:14px 16px;margin-top:14px;display:flex;align-items:center;gap:14px;font-size:14px}
.asmb .sp{flex:1}
.asmb input{width:22px;height:22px;accent-color:#111}
.asmb .mn{font-size:13px;color:#484848;margin-top:4px}
.os{background:#fff;border:1px solid #f0f0f0;padding:0}
.os .hd{background:#f5f5f5;padding:22px 26px;font-size:20px;font-weight:700}
.os .bd{padding:22px 26px}
.os .row{display:flex;justify-content:space-between;align-items:baseline;padding:7px 0;font-size:14px}
.os .tot{display:flex;justify-content:space-between;align-items:baseline;border-top:2px solid var(--ink);margin-top:12px;padding-top:16px;font-size:16px;font-weight:700}
.os .tot .big{font-size:28px}
.os .afterpay{display:flex;gap:10px;align-items:flex-start;margin-top:22px}
.os .am{width:26px;height:26px;background:#111;color:#fff;border-radius:4px;display:flex;align-items:center;justify-content:center;font-weight:700;flex:0 0 auto}
.os .fam{background:#f5f5f5;padding:14px;margin-top:18px;display:flex;gap:12px;align-items:flex-start}
.disc{border-top:1px solid var(--line2);margin-top:22px;padding-top:18px}
.disc .hd{display:flex;justify-content:space-between;font-weight:700;font-size:15px;cursor:pointer}
.disc .body{display:none;padding-top:14px}
.disc.open .body{display:block}
.disc .f{display:flex;gap:10px}
.disc input{flex:1;height:46px;border:1px solid var(--line);border-radius:4px;padding:0 12px;font-size:15px;outline:0}
.disc input.err{border:2px solid var(--red)}
.disc .msg{color:var(--red);font-size:13px;margin-top:8px;display:flex;gap:6px;align-items:center;font-weight:700}
.disc .hint{font-size:13px;color:#484848;margin-top:10px}
.payrow{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:24px}
.payrow img{height:22px;width:auto}
.essentials{margin-top:40px;padding:40px 0 80px;border-top:1px solid var(--line)}
.essentials h2{font-size:24px;font-weight:400;margin-bottom:22px}
.essgrid{display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}
.essgrid .it{background:#fff;padding:18px;display:flex;flex-direction:column}
.essgrid img{width:100%;aspect-ratio:1/1;object-fit:contain;margin-bottom:14px}
.essgrid .nm{font-weight:700;font-size:14px}
.essgrid .ds{font-size:12px;color:#484848;margin-top:2px;min-height:32px}
.essgrid .pr{font-size:22px;font-weight:700;margin-top:6px}
.essgrid .was{font-size:12px;color:#484848;text-decoration:line-through}
.essgrid .badge2{background:var(--yellow);color:#111;font-size:20px;font-weight:700;padding:2px 8px;display:inline-block}
.essgrid .av{font-size:12px;margin-top:10px;color:#484848}
.essgrid .av div{display:flex;gap:8px;align-items:center;padding:2px 0}

/* ---------- overlays ---------- */
.ov{position:fixed;inset:0;z-index:90;display:flex;justify-content:flex-end;background:rgba(0,0,0,.35)}
.ov.center{align-items:center;justify-content:center}
.drawer{background:#fff;width:480px;height:100%;display:flex;flex-direction:column;box-shadow:-4px 0 30px rgba(0,0,0,.2);animation:slide .18s ease}
.drawer.wide{width:610px}
@keyframes slide{from{transform:translateX(30px);opacity:.4}to{transform:none;opacity:1}}
.drawer .dh{padding:22px 26px;display:flex;justify-content:space-between;align-items:flex-start}
.drawer .db{padding:0 26px;overflow:auto;flex:1}
.drawer .df{padding:20px 26px;border-top:1px solid var(--line2)}
.drawer h2{font-size:26px;margin-bottom:12px}
.zipin{width:100%;height:52px;border:1px solid var(--line);border-radius:4px;padding:0 14px;font-size:17px;outline:0}
.zipin.ok{border:2px solid var(--green)}
.zipin.err{border:2px solid var(--red)}
.ziplbl{font-size:14px;font-weight:700;margin:18px 0 6px}
.ziplbl .req{color:var(--red)}
.ziphelp{font-size:12px;color:#484848;margin-top:6px}
.ziphelp.ok{color:var(--green);font-weight:700;display:flex;gap:6px;align-items:center}
.ziperr{font-size:12px;color:var(--red);font-weight:700;margin-top:6px}
.storelist{margin-top:12px}
.storelist button{display:block;width:100%;text-align:left;padding:18px 0;border-bottom:1px solid var(--line2)}
.storelist button:hover{background:#f7f7f7}
.storelist .n{font-weight:700}
.storelist .a{font-size:13px;color:#484848}
.storelist button.on .n{color:var(--blue)}

.modal{background:#fff;border-radius:6px;max-width:1140px;width:calc(100% - 80px);max-height:88vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 70px rgba(0,0,0,.35)}
.modal .mh{display:flex;justify-content:flex-end;padding:12px 16px}
.modal .mb{overflow:auto;padding:0 0 30px}
.modal.media{max-width:1320px;width:calc(100% - 60px);height:88vh;border-radius:0}
.mtags{display:flex;gap:22px;justify-content:center;margin:2px 0 22px}
.mtags button{font-weight:700;color:#484848;padding-bottom:6px}
.mtags button.on{color:#111;box-shadow:inset 0 -2px 0 var(--ink)}
.mgrid{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:0 30px}
.mgrid img{width:100%;object-fit:cover;background:#f5f5f5}
.reviewswrap{display:grid;grid-template-columns:320px 1fr}
.rl{padding:30px 30px 40px;background:#f5f5f5}
.rl .avg{font-size:56px;font-weight:700;text-align:center}
.rl .stars{text-align:center;font-size:22px;display:block}
.rl .based{text-align:center;color:#484848;margin-bottom:24px}
.rbar{display:grid;grid-template-columns:34px 1fr 34px;gap:10px;align-items:center;font-size:13px;padding:6px 0}
.rbar .track{height:8px;background:#dcdcdc;border-radius:4px}
.rbar .fill{height:8px;background:var(--blue);border-radius:4px}
.subrow{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid var(--line);font-size:14px}
.dots{display:flex;gap:2px}
.dots i{width:9px;height:9px;border-radius:50%;background:#111;display:block}
.dots i.off{background:#d0d0d0}
.rr{padding:26px 34px;overflow:auto}
.rr h2{font-size:38px;margin-bottom:18px}
.rrf{display:flex;gap:12px;margin-bottom:22px;position:relative}
.rrf .b{display:flex;align-items:center;gap:8px;background:#f0f0f0;border-radius:100px;padding:11px 18px;font-weight:700}
.rrf .b.on{background:#fff;box-shadow:0 0 0 2px #111}
.sortmenu{position:absolute;top:56px;left:110px;background:#fff;border-radius:6px;box-shadow:0 8px 34px rgba(0,0,0,.25);padding:12px 0;z-index:5;min-width:230px}
.sortmenu label{display:flex;gap:12px;align-items:center;padding:11px 20px;cursor:pointer;font-size:14px}
.sortmenu label:hover{background:#f5f5f5}
.sortmenu .dot{width:20px;height:20px;border-radius:50%;border:2px solid #767676;display:flex;align-items:center;justify-content:center}
.sortmenu label.on .dot{border-color:#111}
.sortmenu label.on .dot:after{content:'';width:10px;height:10px;border-radius:50%;background:#111}
.tabs2{display:flex;gap:26px;border-bottom:1px solid var(--line);margin-bottom:20px}
.tabs2 button{padding-bottom:12px;font-weight:700;color:#484848}
.tabs2 button.on{color:#111;box-shadow:inset 0 -2px 0 var(--ink)}
.summary{background:#f0f0f0;padding:20px 22px;border-radius:4px;margin-bottom:22px}
.summary h4{font-size:16px;margin-bottom:10px;display:flex;align-items:center;gap:10px}
.summary p{font-size:14px;color:#333}
.summary .sf{display:flex;justify-content:flex-end;gap:18px;margin-top:14px;font-size:13px;font-weight:700}
.topics{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0 26px}
.topics .t{border:2px solid #111;border-radius:100px;padding:7px 14px;font-size:13px;font-weight:700}
.topics .t.alt{border:0;background:#f0f0f0;font-weight:400}
.review{border-top:1px solid var(--line2);padding:22px 0}
.review .hd{display:flex;justify-content:space-between;align-items:center}
.review h4{font-size:16px;margin:8px 0 6px}
.review p{font-size:14px}
.review .ft{display:flex;align-items:center;gap:14px;margin-top:16px;font-size:13px}
.review .who{background:#f0f0f0;border-radius:100px;padding:7px 16px;font-weight:700}
.review .rep{border:2px solid #111;border-radius:100px;padding:8px 18px;font-weight:700;font-size:13px}
.review .resp{background:#f5f5f5;padding:16px;margin-top:14px;font-size:13px;border-radius:4px}

/* added-to-bag panel */
.added .dh{background:#fff}
.added .ok{width:36px;height:36px;border-radius:50%;background:var(--green);color:#fff;display:flex;align-items:center;justify-content:center}
.added .item{display:grid;grid-template-columns:70px 1fr auto;gap:14px;padding-bottom:22px;border-bottom:1px solid var(--line2)}
.added .item img{width:70px;height:70px;object-fit:contain;background:#f5f5f5}
.added .msg{font-size:14px;margin:0 0 10px}
.added .yl{font-weight:700;font-size:16px;margin:22px 0 12px}
.added .like{display:grid;grid-template-columns:70px 1fr auto;gap:14px;padding:16px 0;border-bottom:1px solid var(--line2);align-items:flex-start}
.added .like img{width:70px;height:70px;object-fit:contain;background:#f5f5f5}
.added .fam{color:var(--blue);font-weight:700;font-size:13px}
.added .nm{font-weight:700;font-size:14px}
.added .pr{font-size:18px;font-weight:700}
.added .ship{display:flex;gap:10px;font-size:13px;color:#484848;padding:16px 0;text-decoration:underline}

/* toast */
#toast{position:fixed;top:16px;right:16px;z-index:120;display:flex;flex-direction:column;gap:10px}
.toast{background:#111;color:#fff;padding:16px 18px;display:flex;align-items:center;gap:18px;min-width:330px;border-radius:4px;box-shadow:0 6px 24px rgba(0,0,0,.3);animation:tin .2s ease}
@keyframes tin{from{transform:translateY(-8px);opacity:0}to{transform:none;opacity:1}}
.toast .txt{flex:1;font-size:14px}
.toast .undo{font-weight:700;color:#fff;text-decoration:underline}
.toast .x{width:22px;height:22px;display:flex;align-items:center;justify-content:center}

/* product page bottom cards */
.returns{display:flex;gap:12px;align-items:flex-start;border:1px solid var(--line);padding:16px 18px;margin-top:18px;font-size:14px}
.infoline{display:flex;gap:10px;align-items:flex-start;font-size:13px;color:#484848;padding:10px 0}

/* footer */
.foot{border-top:1px solid var(--line);margin-top:60px;padding:40px 0 70px;font-size:13px;color:#484848}
.foot .cols{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.foot h4{color:#111;font-size:14px;margin-bottom:10px}
.foot a{display:block;padding:5px 0}
.foot a:hover{text-decoration:underline}
.legend{display:grid;grid-template-columns:auto 1fr;gap:8px 14px}
.fake{padding:60px 0}

/* responsive-ish safety */
@media (max-width:1180px){
  .grid{grid-template-columns:repeat(3,1fr)}
  .meganav .body{grid-template-columns:1fr 1fr}
  .pd{grid-template-columns:90px 1fr}
  .pd-info{grid-column:2}
  .bagwrap{grid-template-columns:1fr}
  .accgrid,.essgrid{grid-template-columns:repeat(3,1fr)}
}
@media (max-width:900px){
  .grid{grid-template-columns:repeat(2,1fr)}
  .search-head,.search-body,.hero,.revcard,.inc,.meas{grid-template-columns:1fr}
  .drawer{width:100%}
}

