  /* ---------- routing ---------- */
  function parseHash() {
    var raw = location.hash.replace(/^#/, '') || '/';
    var qi = raw.indexOf('?');
    var path = qi >= 0 ? raw.slice(0, qi) : raw;
    var qs = qi >= 0 ? raw.slice(qi + 1) : '';
    var parts = path.split('/').filter(Boolean);
    var q = '';
    qs.split('&').forEach(function (kv) { var a = kv.split('='); if (a[0] === 'q') q = decodeURIComponent(a[1] || ''); });
    if (parts.length === 0) return { name: 'home' };
    if (parts[0] === 'search') return { name: 'search', q: q || 'besta' };
    if (parts[0] === 'compare') return { name: 'compare' };
    if (parts[0] === 'bag') return { name: 'bag' };
    if (parts[0] === 'p' && parts[1]) return { name: 'product', id: parts[1] };
    return { name: 'home' };
  }
  function go(href) { location.hash = href; }

