  }
  function sortedIds() {
    var ids = searchIds();
    var arr = ids.map(function (id) { return P(id); }).filter(Boolean);
    var s = UI.sort;
    if (s === 'price_asc') arr.sort(function (a, b) { return a.member_price - b.member_price; });
    else if (s === 'price_desc') arr.sort(function (a, b) { return b.member_price - a.member_price; });
    else if (s === 'rating') arr.sort(function (a, b) { return b.rating - a.rating; });
    else if (s === 'name') arr.sort(function (a, b) { return a.name.localeCompare(b.name); });
    else if (s === 'popular') arr.sort(function (a, b) { return b.review_count - a.review_count; });
    else if (s === 'newest') arr.reverse();
    return arr;
  }
  var SORTS = [['best_match', 'Best match'], ['price_asc', 'Price: low to high'], ['price_desc', 'Price: high to low'],
