  /* ============================================================ PRODUCT */
  function renderProduct(id) {
    var p = P(id);
    if (!p) return '<div class="wrap fake"><h1>Product not found</h1><p style="margin-top:16px"><a class="btn black" data-act="nav" data-href="#/search?q=besta">Back to search</a></p></div>';
    var gal = p.gallery || [p.image];
    var cur = UI.mainImg[id] || gal[0];
    if (gal.indexOf(cur) < 0) cur = gal[0];
    var qty = UI.qty[id] || 1;

    var crumbs = (p.crumb || CRUMB_GEN).map(function (c, i) {
      var last = i === (p.crumb || CRUMB_GEN).length - 1;
