          (id === '20293568' ? '<div class="note">' + I.info + '<span>BESTÅ supporting leg sold separately.</span></div>' : '') +
          swHtml +
          '<div class="pd-sec"><h3>Design it yourself</h3><div class="sub">Customise BESTÅ in our planning tool</div></div>' +
          '<div class="pd-sec"><h3>How to get it</h3>' + howToGetIt(p) + '</div>' +
          '<div class="qtyrow"><div class="stepper"><button data-act="pdp-minus" data-id="' + id + '"' + (qty <= 1 ? ' disabled' : '') + '>' + I.minus + '</button>' +
