      '<div class="r">' + I.store + '<div><span class="dot g"></span><b style="display:inline"> In stock in IKEA ' + esc(st) + '</b><div class="s">Opens at 10:00 AM<br><a style="text-decoration:underline">Find in store</a></div></div></div>' +
      '<div class="r">' + I.store + '<div><span class="dot g"></span><b style="display:inline"> Click and collect at IKEA ' + esc(st) + '</b><div class="s">From $2.00 or <a style="text-decoration:underline">Free with IKEA Family</a></div></div></div>' +
      '<div class="r">' + I.truck + '<div><span class="dot g"></span><b style="display:inline"> Home delivery to ' + esc(ST.location.zip) + '</b></div></div>' +
      '</div>';
