  function renderPdTabs(p) {
    var tabs = [['overview', 'Overview'], ['details', 'Product details'], ['measurements', 'Measurements'], ['included', "What's included"]];
    var bar = tabs.map(function (t) { return '<button class="' + (UI.pdTab === t[0] ? 'on' : '') + '" data-act="pd-tab" data-tab="' + t[0] + '">' + t[1] + '</button>'; }).join('');
    var body = '';
    if (UI.pdTab === 'overview') {
      body = '<h3 style="font-size:20px;margin-bottom:14px">' + esc(p.name) + ' ' + esc(p.description) + '</h3>' +
        '<p style="max-width:760px">BESTÅ storage system is a flexible, modular solution that lets you build exactly the storage you need. The frame is easy to assemble and the doors and drawers keep dust away and clutter out of sight. Combine frames, doors, legs and interior organisers — knobs and handles are sold separately so you can finish the look your way.</p>' +
        '<div style="margin-top:22px;max-width:760px">' +
        '<div class="infoline">' + I.info + '<span>Design and build your own BESTÅ in the IKEA planning tool.</span></div>' +
        '<div class="infoline">' + I.info + '<span>Wall-anchoring kit included — always secure furniture to the wall.</span></div></div>';
    } else if (UI.pdTab === 'details') {
      var rows = (p.details || [['Width', (p.dims ? p.dims.width : '')], ['Depth', (p.dims ? p.dims.depth : '')], ['Height', (p.dims ? p.dims.height : '')], ['Max load/shelf', (p.dims ? p.dims.load : '')]]);
      body = '<div class="mtable" style="max-width:900px">' + rows.map(function (r, i) {
        return '<div class="row"' + (i ? ' style="border-top:1px solid var(--line)"' : '') + '><span>' + esc(r[0]) + '</span><b>' + esc(r[1]) + '</b></div>';
      }).join('') + '</div>';
    } else if (UI.pdTab === 'measurements') {
      var d = p.dims || { width: '47 1/4 "', depth: '16 1/2 "', height: '29 1/8 "', load: '44 lb' };
      body = '<div class="meas"><div class="ill"><img src="/assets/media-317.jpg" alt="Measurement drawing"></div>' +
        '<div class="mtable"><div class="h"><span>Measurements</span>' + I.chev + '</div>' +
        '<div class="grid2"><div class="cell"><span class="k">Width</span><span class="v">' + esc(d.width) + '</span></div>' +
        '<div class="cell"><span class="k">Depth</span><span class="v">' + esc(d.depth || '16 1/2 "') + '</span></div>' +
        '<div class="cell"><span class="k">Height</span><span class="v">' + esc(d.height) + '</span></div>' +
        '<div class="cell"><span class="k">Max load/shelf</span><span class="v">' + esc(d.load || '44 lb') + '</span></div></div>' +
        '<div class="h" style="border-top:1px solid var(--line);border-bottom:0"><span>Packaging</span>' + I.chev + '</div></div></div>';
    } else {
      var comps = p.components;
