        body = '<p>This product is sold as a single unit and does not contain separate components.</p>';
      } else {
        body = '<p style="margin-bottom:24px">This product is made up of more than one component. You can find the details of these components below.</p>' +
          '<div class="inc"><div class="list">' + comps.map(function (c) {
            return '<div class="compc" ' + (c.link ? 'data-act="nav" data-href="#/p/' + c.link + '" style="cursor:pointer"' : '') + '>' +
              '<div class="im"><img src="' + c.img + '"></div>' +
              '<div><div class="q">' + c.qty + ' x ' + esc(c.type) + '</div><div class="nm">' + esc(c.name) + '</div>' +
              (c.desc ? '<div class="ds">' + esc(c.desc) + '</div>' : '') + '<div class="art">' + esc(c.art) + '</div></div></div>';
          }).join('') + '</div>' +
          '<div class="hero2"><img src="' + p.image + '"></div></div>';
      }
    }
    return '<div class="pdtabs"><div class="wrap" style="padding:0"><div class="bar">' + bar + '</div><div class="panel">' + body + '</div></div></div>';
