  function renderReviewSummary(p) {
    return '<div class="revsec"><div class="wrap"><div class="revcard">' +
      '<div class="l">Customer reviews</div>' +
      '<div class="r"><div><div class="bignum">' + p.rating.toFixed(1) + '</div>' + stars(p.rating) +
        '<div style="color:#484848;font-size:13px">Average rating</div></div>' +
        '<div><div class="rev">' + p.review_count + '</div><div style="color:#484848;font-size:13px">Reviews</div></div>' +
        '<div style="flex:1;text-align:center"><button class="btn ghost" style="padding:14px 40px" data-act="open-reviews" data-id="' + p.id + '">Show all reviews</button></div>' +
      '</div></div></div></div>';
