  function renderAccessories(p) {
    return '<div class="access wrap"><div class="hd"><h2>Accessories for ' + esc(p.name) + '</h2>' +
      '<button class="btn black" data-act="nav" data-href="#/search?q=accessories">Show all accessories</button></div>' +
      '<div class="accgrid">' + ACCESSORIES.map(function (a) { return '<div class="it"><img src="' + a + '"></div>'; }).join('') + '</div></div>';
  }

  /* ============================================================ BAG */
  function bagTotals() {
    var prods = 0, savings = 0, asmb = 0;
    ST.bag.forEach(function (l) {
      var p = P(l.id); if (!p) return;
      prods += p.regular_price * l.qty;
      savings += (p.regular_price - p.member_price) * l.qty;
      if (l.assembly && p.assembly_per_unit) asmb += p.assembly_per_unit * l.qty;
    });
    return { prods: prods, savings: savings, asmb: asmb, total: prods + asmb };
  }

  function renderBag() {
    var t = bagTotals();
    var zip = ST.location.zip;
    var delivery = zip ?
      '<div class="dcards">' +
        '<div class="dcard"><div class="hd">' + I.truck + '<span>Delivery to ' + esc(zip) + '</span></div>' +
          '<div><span class="dot g" style="background:var(--green);display:inline-block;width:9px;height:9px;border-radius:50%"></span> Starting at $' + LOC.delivery_from.toFixed(2) + '</div>' +
