        '<div class="dcard"><div class="hd">' + I.store + '<span>Pick up at IKEA ' + esc(ST.location.store || LOC.store) + '</span></div>' +
          '<div><span style="background:var(--green);display:inline-block;width:9px;height:9px;border-radius:50%"></span> $2.00 or <span class="l">Free with IKEA Family</span></div>' +
          '<div class="g">Get it tomorrow</div></div>' +
        '<div class="dcard"><div class="hd">' + I.layers + '<span>Collect at CRST/N…</span></div>' +
