      '</div>' :
      '<div class="dcards" style="grid-template-columns:1fr"><div class="dcard"><div class="hd">' + I.truck + '<span>Enter your ZIP code to see delivery options</span></div>' +
        '<a class="l" data-act="open-location">Enter ZIP code</a></div></div>';

    var lines = ST.bag.length ? ST.bag.map(function (l, idx) { return bagLine(l, idx); }).join('') :
      '<div style="padding:50px 0"><p>Your shopping bag is empty.</p><p style="margin-top:16px"><a class="btn black" data-act="nav" data-href="#/search?q=besta">Start shopping</a></p></div>';

    var payIcons = PAY_ICONS.map(function (i) { return '<img src="' + i + '">'; }).join('');

    return '<div class="wrap"><div class="bagwrap">' +
      '<div><h1>Shopping bag</h1>' + delivery +
        '<div class="pickup">' + I.cart + '<div>Pick up yourself at ' + esc(ST.location.store || LOC.store) + '</div></div>' +
        lines + '</div>' +
      '<aside class="os"><div class="hd">Order summary</div><div class="bd">' +
        '<div class="row"><span>Products</span><span>' + money(t.prods) + '</span></div>' +
        (t.asmb ? '<div class="row"><span>Assembly service</span><span>' + money(t.asmb) + '</span></div>' : '') +
        '<div class="row" style="color:#767676"><span>Shipping costs are calculated at checkout</span></div>' +
        '<div class="tot"><span>Total excluding tax</span><span class="big">' + big(t.total) + '</span></div>' +
        '<div class="afterpay"><span class="am">$</span><div><b>Afterpay</b><div>4 interest-free payments of $' + Math.ceil(t.total / 4) + ' + tax. <a style="text-decoration:underline">Learn more</a></div></div></div>' +
        '<div style="margin-top:18px"><b>IKEA Visa Credit Card</b><div style="font-size:13px">Earn 5% in rewards at IKEA using the IKEA Visa Credit Card*. <a style="text-decoration:underline">Learn more</a></div></div>' +
        '<div class="fam"><img src="/assets/media-352.svg" style="width:40px" alt=""><div><b>Save $' + t.savings.toFixed(2) + ' with IKEA Family</b><div><a style="text-decoration:underline">Join for free or log in</a></div></div></div>' +
        '<div class="fam" style="background:#fff;gap:12px"><span style="width:24px;height:24px;border-radius:50%;background:var(--yellow);display:inline-flex;align-items:center;justify-content:center">' + I.family + '</span><div><b>Collect ' + Math.round(t.total) + ' points with IKEA Family</b><div><a style="text-decoration:underline">Explore what you can get</a></div></div></div>' +
        '<div class="disc' + (UI.discountOpen ? ' open' : '') + '"><div class="hd" data-act="toggle-discount"><span>+ &nbsp;Apply discount code</span>' + I.chev + '</div>' +
          '<div class="body"><div class="f"><input id="discInput" class="' + (UI.discountError ? 'err' : '') + '" placeholder="" value="' + esc(UI.discountCode) + '">' +
            '<button class="btn black" data-act="apply-discount">Apply</button></div>' +
            (UI.discountError ? '<div class="msg">' + I.info + 'Please enter a valid discount code.</div>' : '') +
            '<div class="hint">Enter the code without any space between letters. Gift cards can be exchanged later in the process.</div></div></div>' +
        '<button class="btn blue full" style="margin-top:24px;justify-content:space-between;padding:20px 24px" data-act="checkout">Continue to checkout <span style="width:34px;height:34px;border-radius:50%;background:#fff;display:flex;align-items:center;justify-content:center">' + I.chevR + '</span></button>' +
