  function bagLine(l, idx) {
    var p = P(l.id); if (!p) return '';
    var lineTotal = p.regular_price * l.qty;
    var saved = (p.regular_price - p.member_price) * l.qty;
    var per = p.pack_size ? ('/' + p.pack_size + ' pack') : '';
    var comps = p.components ?
      '<a class="lnk" data-act="open-parts" data-id="' + p.id + '">Show included parts</a>' + '<br>' : '';
    var asmb = p.assembly_per_unit ?
      '<div class="asmb">' + I.task + '<div><a style="text-decoration:underline" data-act="noop">Assembly by Taskrabbit for ' + esc(p.name) + (l.qty > 1 ? ' (' + l.qty + ')' : '') + '</a>' +
      (p.id === '20293568' ? '<div class="mn">*Minimum fee for assembly service is $52.00. <a style="text-decoration:underline">Learn more</a></div>' : '') + '</div>' +
      '<span class="sp"></span><b>$' + (p.assembly_per_unit * l.qty).toFixed(2) + '</b>' +
      '<input type="checkbox" data-asmb="' + p.id + '"' + (l.assembly ? ' checked' : '') + '></div>' : '';

    return '<div class="line">' +
      '<div><div class="im"><img src="' + p.image + '"></div><div class="art">' + p.id.slice(0, 3) + '.' + p.id.slice(3, 6) + '.' + p.id.slice(6) + '</div></div>' +
