        '<a class="sv" data-act="noop">' + pct(p) + '% off, save $' + saved.toFixed(2) + ' with IKEA Family</a>' +
        '<div class="unit">' + money(p.regular_price) + per + '/piece</div>' +
        comps +
        '<div class="avail"><div><span style="background:var(--green);display:inline-block;width:9px;height:9px;border-radius:50%"></span>Available for delivery</div>' +
        '<div><span style="background:var(--green);display:inline-block;width:9px;height:9px;border-radius:50%"></span>Available for Click &amp; collect</div>' +
        '<div><span style="background:var(--green);display:inline-block;width:9px;height:9px;border-radius:50%"></span>Available for Collect near you</div></div>' +
        '<div class="acts"><a style="text-decoration:underline" data-act="save-later" data-idx="' + idx + '">Save for later</a><span class="sp"></span>' +
