  /* ---------- toast ---------- */
  function toast(msg, undoLabel, undoFn) {
    var el = document.createElement('div');
    el.className = 'toast';
    el.innerHTML = '<span class="txt">' + msg + '</span>' +
      (undoLabel ? '<button class="undo">' + undoLabel + '</button>' : '') +
      '<button class="x" aria-label="Close">' + I.close + '</button>';
    toastWrap.appendChild(el);
    var timer = setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 7000);
    if (undoLabel && undoFn) {
      el.querySelector('.undo').addEventListener('click', function () {
        clearTimeout(timer);
        undoFn();
        if (el.parentNode) el.parentNode.removeChild(el);
      });
    }
    el.querySelector('.x').addEventListener('click', function () {
      clearTimeout(timer);
      if (el.parentNode) el.parentNode.removeChild(el);
    });
  }

  /* ============================================================ RENDER */
  function render() {
    var route = UI.route;
    var html = renderTop() + renderHeader(route);
    if (UI.meganav && route.name === 'home') html += renderMeganav();
    if (route.name === 'home') html += renderHome();
    else if (route.name === 'search') html += renderSearch(route);
    else if (route.name === 'compare') html += renderCompare();
    else if (route.name === 'bag') html += renderBag();
    else if (route.name === 'product') html += renderProduct(route.id);
    if (!ST.cookieHidden) html += renderCookie();
    app.innerHTML = html;
    app.className = UI.meganav ? 'mnav-open' : '';
    modals.innerHTML = renderOverlays();
    updateSug();
  }

  function updateSug() {
    var inp = document.getElementById('searchInput');
    var box = document.getElementById('sugBox');
    if (!inp || !box) return;
    var norm = (inp.value || '').trim().toLowerCase();
    if (!norm || !UI.searchOpen) { box.classList.remove('on'); return; }
    var matches = SUGGESTIONS.filter(function (s) {
      return s.toLowerCase().indexOf(norm) >= 0 && s.toLowerCase() !== norm;
    }).slice(0, 7);
    var rows = '<a data-act="do-search-now"><span>' + I.search + '</span><span>' + esc(inp.value) + '</span></a>';
    rows += matches.map(function (s) {
      return '<a data-act="sug" data-q="' + esc(s) + '"><span>' + I.search + '</span><span>' + esc(s) + '</span></a>';
    }).join('');
    box.innerHTML = rows;
    box.classList.add('on');
  }/* ============================================================ ACTIONS */
  function navigate(href) {
    UI.overlay = null;
    UI.searchOpen = false;
    if (location.hash === href) { UI.route = parseHash(); render(); window.scrollTo(0, 0); }
    else location.hash = href;
  }

  function findLine(id) {
    for (var i = 0; i < ST.bag.length; i++) if (ST.bag[i].id === id) return ST.bag[i];
    return null;
  }

  function addToBag(id, qty) {
    qty = qty || 1;
    var l = findLine(id);
    if (l) l.qty += qty; else ST.bag.push({ id: id, qty: qty, assembly: false });
    persist();
    var likes;
    if (id === '20293568' || id === '60293566') likes = ['80261258', '00291848'];
    else if (id === '29612189' || id === '29209829' || id === '89209829') likes = ['09590409', '20293568'];
    else likes = ['00295554', '80261258'];
    UI.overlay = { type: 'added', id: id, qty: qty, likes: likes };
    render();
  }

  function removeLine(idx, save) {
    var l = ST.bag[idx];
    if (!l) return;
    var nm = P(l.id) ? P(l.id).name : 'Item';
    ST.bag.splice(idx, 1);
    persist();
    render();
    toast(nm + (save ? ' was saved for later.' : ' was removed from your shopping bag.'), 'Undo', function () {
      ST.bag.splice(idx, 0, l);
      persist();
      render();
    });
  }

  function changeQty(idx, delta) {
    var l = ST.bag[idx];
    if (!l) return;
    var n = l.qty + delta;
    if (n < 1) return;
    l.qty = n;
    persist();
    render();
  }

  function applyDiscount() {
    var code = (UI.discountCode || '').trim();
    if (!code) { UI.discountError = true; render(); refocus('discInput'); return; }
    UI.discountError = true;
    render();
    refocus('discInput');
  }

  function refocus(id) {
    var el = document.getElementById(id);
    if (el) { el.focus(); if (el.setSelectionRange && el.value) el.setSelectionRange(el.value.length, el.value.length); }
  }

  function saveZip() {
    var v = (UI.zipVal || '').trim();
    if (/^[0-9]{5}$/.test(v)) {
      ST.location.zip = v;
      ST.location.store = (v === LOC.valid_postcode) ? LOC.store : (ST.location.store || LOC.store);
      persist();
      UI.zipOk = true; UI.zipErr = '';
      UI.overlay = null;
      render();
      toast('Delivery and stock availability updated for ' + v + '.');
    } else {
      UI.zipErr = 'Please enter a valid Zip code.';
      UI.zipOk = false;
      render();
      refocus('zipInput');
    }
  }

  /* ============================================================ CLICK */
  document.addEventListener('click', function (e) {
    var el = e.target.closest ? e.target.closest('[data-act]') : null;
    if (!el) {
      if (!(e.target.closest && e.target.closest('.search'))) {
        UI.searchOpen = false;
        var sb = document.getElementById('sugBox');
        if (sb) sb.classList.remove('on');
      }
      return;
    }
    if (el.classList.contains('ov')) { if (e.target === el) closeOverlay(); return; }
    var act = el.getAttribute('data-act');
    var id = el.getAttribute('data-id');

    if (act === 'nav') { navigate(el.getAttribute('data-href')); return; }
    if (act === 'noop' || act === 'helpful' || act === 'report' || act === 'login' || act === 'favourites') return;
    if (act === 'close-overlay') { closeOverlay(); return; }

    if (act === 'toggle-meganav') { UI.meganav = !UI.meganav; UI.meganavTab = 'new'; render(); return; }
    if (act === 'pill') {
      var tab = el.getAttribute('data-tab');
      UI.meganav = true; UI.meganavTab = tab; render();
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    if (act === 'meganav-tab') { UI.meganavTab = el.getAttribute('data-tab'); render(); return; }

    if (act === 'do-search' || act === 'do-search-now') {
      var inp = document.getElementById('searchInput');
      var q = inp && inp.value.trim() ? inp.value.trim() : 'besta';
      UI.searchOpen = false;
      navigate('#/search?q=' + encodeURIComponent(q));
      return;
    }
    if (act === 'sug') { UI.searchOpen = false; navigate('#/search?q=' + encodeURIComponent(el.getAttribute('data-q'))); return; }
    if (act === 'clear-search') {
      var i2 = document.getElementById('searchInput');
      if (i2) { i2.value = ''; i2.focus(); }
      UI.searchVal = ''; UI.searchOpen = false; updateSug();
      var f = el.closest('.search'); if (f) f.classList.remove('filled');
      return;
    }

    if (act === 'acc') {
      var k = el.getAttribute('data-acc');
      UI.accordions[k] = !UI.accordions[k];
      render();
      return;
    }
    if (act === 'set-sort') { UI.sort = el.getAttribute('data-sort'); UI.accordions.sort = false; render(); return; }
    if (act === 'set-color') {
      var c = el.getAttribute('data-color');
      UI.filters.color = (UI.filters.color === c) ? null : c;
      render();
      return;
    }
    if (act === 'clear-color') { UI.filters.color = null; render(); return; }

    if (act === 'compare-close') { ST.compare = []; persist(); render(); return; }
    if (act === 'go-compare') {
      if (ST.compare.length >= 2) navigate('#/compare');
      else toast('Select at least 2 products to compare.');
      return;
    }
    if (act === 'remove-compare') {
      var ci = ST.compare.indexOf(id);
      if (ci >= 0) ST.compare.splice(ci, 1);
      persist(); render();
      return;
    }

    if (act === 'thumb') { UI.mainImg[id] = el.getAttribute('data-img'); render(); return; }
    if (act === 'swatch') {
      var vid = el.getAttribute('data-vid');
      if (vid) { navigate('#/p/' + vid); return; }
      UI.mainImg[id] = el.getAttribute('data-img');
      render();
      return;
    }
    if (act === 'pd-tab') { UI.pdTab = el.getAttribute('data-tab'); render(); return; }
    if (act === 'pdp-plus') { UI.qty[id] = (UI.qty[id] || 1) + 1; render(); return; }
    if (act === 'pdp-minus') { UI.qty[id] = Math.max(1, (UI.qty[id] || 1) - 1); render(); return; }
    if (act === 'add-to-bag') { addToBag(id, parseInt(el.getAttribute('data-qty') || '1', 10) || 1); return; }
    if (act === 'fav') { toast('Saved to your favourites.'); return; }

    if (act === 'open-media') { UI.overlay = { type: 'media', id: id }; UI.mediaTab = 'all'; render(); return; }
    if (act === 'media-tab') { UI.mediaTab = el.getAttribute('data-tab'); render(); return; }
    if (act === 'open-3d') { toast('The 3D planner is not part of this local replica.'); return; }
    if (act === 'open-parts') {
      var ln = findLine(id);
      UI.overlay = { type: 'parts', id: id, qty: ln ? ln.qty : 1 };
      render();
      return;
    }

    if (act === 'save-later') { removeLine(parseInt(el.getAttribute('data-idx'), 10), true); return; }
    if (act === 'remove-line') { removeLine(parseInt(el.getAttribute('data-idx'), 10), false); return; }
    if (act === 'bag-plus') { changeQty(parseInt(el.getAttribute('data-idx'), 10), 1); return; }
    if (act === 'bag-minus') { changeQty(parseInt(el.getAttribute('data-idx'), 10), -1); return; }

    if (act === 'toggle-discount') {
      UI.discountOpen = !UI.discountOpen;
      render();
      if (UI.discountOpen) refocus('discInput');
      return;
    }
    if (act === 'apply-discount') { applyDiscount(); return; }
    if (act === 'checkout') { toast('Checkout is not part of this local replica.'); return; }

    if (act === 'open-location') {
      UI.overlay = { type: 'location' };
      UI.zipVal = ST.location.zip || '';
      UI.zipOk = /^[0-9]{5}$/.test(UI.zipVal);
      UI.zipErr = '';
      render();
      refocus('zipInput');
      return;
    }
    if (act === 'save-zip') { saveZip(); return; }
    if (act === 'open-store') { UI.overlay = { type: 'store' }; UI.storeFilter = ''; render(); return; }
    if (act === 'select-store') {
      var s = el.getAttribute('data-store');
      ST.location.store = s;
      ST.location.zip = ST.location.zip || LOC.valid_postcode;
      persist();
      UI.overlay = null;
      render();
      return;
    }

    if (act === 'open-reviews') { UI.overlay = { type: 'reviews', id: id }; render(); return; }
    if (act === 'review-filter') { UI.reviewFilterOpen = !UI.reviewFilterOpen; UI.reviewSortOpen = false; render(); return; }
    if (act === 'review-sort') { UI.reviewSortOpen = !UI.reviewSortOpen; UI.reviewFilterOpen = false; render(); return; }
    if (act === 'review-filter-set') {
      var st = parseInt(el.getAttribute('data-star'), 10);
      UI.reviewFilter = st ? st : null;
      UI.reviewFilterOpen = false;
      render();
      return;
    }
    if (act === 'review-sort-set') {
      UI.reviewSort = el.getAttribute('data-sort');
      UI.reviewSortOpen = false;
      render();
      return;
    }
    if (act === 'review-country') { UI.reviewCountry = el.getAttribute('data-c'); render(); return; }
    if (act === 'toggle-summary') { UI.reviewSummary = !UI.reviewSummary; render(); return; }
    if (act === 'write-review') { UI.reviewForm = 'open'; uiReviewCapture(); render(); return; }
    if (act === 'form-star') { uiReviewCapture(); UI.reviewFormStar = parseInt(el.getAttribute('data-star'), 10); render(); return; }
    if (act === 'close-review-form') { UI.reviewForm = null; render(); return; }
    if (act === 'submit-review') {
      uiReviewCapture();
      if (!UI.reviewFormStar || !(UI.reviewFormTitle || '').trim() || !(UI.reviewFormBody || '').trim()) {
        toast('Please add a rating, a title and your review text.');
        render();
        return;
      }
      UI.reviewForm = 'done';
      UI.reviewFormStar = 0; UI.reviewFormTitle = ''; UI.reviewFormBody = ''; UI.reviewFormName = '';
      render();
      toast('Thank you! Your review has been submitted.');
      return;
    }

    if (act === 'cookie-ok') { ST.cookieHidden = true; persist(); render(); return; }
    if (act === 'cookie-priv') { ST.cookieHidden = true; persist(); render(); toast('Your privacy choices were saved.'); return; }
  });

  function uiReviewCapture() {
    var t = document.getElementById('rvTitle');
    var b = document.getElementById('rvBody');
    var n = document.getElementById('rvName');
    if (t) UI.reviewFormTitle = t.value;
    if (b) UI.reviewFormBody = b.value;
    if (n) UI.reviewFormName = n.value;
  }/* ============================================================ INPUT */
  document.addEventListener('input', function (e) {
    var t = e.target;
    if (!t || !t.id) return;

    if (t.id === 'searchInput') {
      UI.searchVal = t.value;
      UI.searchOpen = true;
      var f = t.closest('.search');
      if (f) { if (t.value) f.classList.add('filled'); else f.classList.remove('filled'); }
      updateSug();
      return;
    }

    if (t.id === 'zipInput') {
      UI.zipVal = t.value;
      var ok = /^[0-9]{5}$/.test(t.value.trim());
      UI.zipOk = ok;
      if (ok) { UI.zipErr = ''; t.classList.add('ok'); t.classList.remove('err'); }
      else { t.classList.remove('ok'); t.classList.remove('err'); }
      var help = t.parentNode.querySelector('.ziphelp') || t.parentNode.querySelector('.ziperr');
      if (help) {
        if (ok) {
          help.className = 'ziphelp ok';
          help.innerHTML = '<span style="display:inline-flex;vertical-align:-3px">' + checkGreen + '</span> e.g. 19428';
        } else if (help.className.indexOf('ziperr') === 0) {
          help.className = 'ziphelp';
          help.innerHTML = 'e.g. 19428';
        }
      }
      var saveBtn = document.querySelector('[data-act="save-zip"]');
      if (saveBtn) saveBtn.className = 'btn full ' + (ok ? 'black' : 'gray');
      return;
    }

    if (t.id === 'storeSearch') {
      UI.storeFilter = t.value;
      render();
      var si = document.getElementById('storeSearch');
      if (si) { si.focus(); if (si.setSelectionRange) si.setSelectionRange(si.value.length, si.value.length); }
      return;
    }

    if (t.id === 'discInput') {
      UI.discountCode = t.value;
      if (t.classList.contains('err')) { t.classList.remove('err'); UI.discountError = false; }
      return;
    }
  });

  document.addEventListener('focusin', function (e) {
    var t = e.target;
    if (t && t.id === 'searchInput') { UI.searchOpen = true; updateSug(); }
  });

  document.addEventListener('change', function (e) {
    var t = e.target;
    if (!t || !t.getAttribute) return;

    var cid = t.getAttribute('data-cmp');
    if (cid) {
      var i = ST.compare.indexOf(cid);
      if (t.checked) {
        if (i < 0) {
          if (ST.compare.length >= 5) { t.checked = false; toast('You can compare up to 5 products.'); return; }
          ST.compare.push(cid);
        }
      } else if (i >= 0) {
        ST.compare.splice(i, 1);
      }
      persist();
      render();
      return;
    }

    var aid = t.getAttribute('data-asmb');
    if (aid) {
      var l = findLine(aid);
      if (l) { l.assembly = !!t.checked; persist(); render(); }
      return;
    }
  });

  document.addEventListener('submit', function (e) {
    if (e.target && e.target.id === 'searchForm') {
      e.preventDefault();
      var inp = document.getElementById('searchInput');
      var q = inp && inp.value.trim() ? inp.value.trim() : 'besta';
      UI.searchOpen = false;
      navigate('#/search?q=' + encodeURIComponent(q));
    }
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' || e.keyCode === 27) {
      if (UI.overlay) { UI.overlay = null; render(); return; }
      if (UI.meganav) { UI.meganav = false; render(); return; }
      return;
    }
    if (e.key === 'Enter' || e.keyCode === 13) {
      var t = e.target;
      if (!t) return;
      if (t.id === 'zipInput') { e.preventDefault(); saveZip(); return; }
      if (t.id === 'discInput') { e.preventDefault(); applyDiscount(); return; }
      if (t.id === 'storeSearch') { e.preventDefault(); render(); return; }
    }
  });

  /* ============================================================ BOOT */
  window.addEventListener('hashchange', function () {
    UI.route = parseHash();
    UI.overlay = null;
    UI.searchOpen = false;
    UI.storeFilter = '';
    UI.reviewSortOpen = false;
    UI.reviewFilterOpen = false;
    UI.zipErr = '';
    render();
    window.scrollTo(0, 0);
  });

  UI.route = parseHash();
  render();

})();
